// spec: specs/orders.md §9 · кейсы .qa/tests/orders/ord-24-walk-in-row-total-phone-widths.md, ord-25-qty-buttons-touch-44.md
// seed: tests/seed.admin.spec.ts
// #a88293 (עבר QA 25.10): «מכירה מיידית» на телефоне 320–414 — «סה"כ» строки (₪1,000.00 / ₪10,000.00 / ₪100,000.00) целиком,
//   отдельным рядом под полем цены, не пересекается с ним; страница без горизонтальной прокрутки; 820/1440 — табличный вид.
// #428d8a (עבר QA 25.10): «+»/«−» 44×44 на 360/390/820 (сенсорная эмуляция → @iphone), не пересекаются; «−» disabled при 1.
// Данные: свой товар QA-AUTO-a882-<ts> (₪1, остаток 5 «ללא מקום»); «רישום המכירה» НЕ нажимается — продажа не регистрируется.
// afterAll: товар удаляется.
import { test, expect, Page, Locator } from '@playwright/test';
import { auth, createStockedProduct, cleanup } from './_qa-order';

test.use({ storageState: auth('admin') });

type Box = { x: number; y: number; width: number; height: number };
const overlapArea = (a: Box, b: Box) =>
  Math.max(0, Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x)) *
  Math.max(0, Math.min(a.y + a.height, b.y + b.height) - Math.max(a.y, b.y));

async function box(l: Locator, what: string): Promise<Box> {
  await expect(l, what).toBeVisible();
  return (await l.boundingBox())!;
}

async function noHorizontalScroll(page: Page, what: string) {
  const d = await page.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
  expect(d[0], `${what}: ширина страницы ${d[0]} = ширине экрана ${d[1]}`).toBeLessThanOrEqual(d[1]);
}

test.describe('orders — מכירה מיידית: סכום השורה בטלפון וכפתורי +/− למגע (#a88293 #428d8a)', () => {
  test.describe.configure({ mode: 'default' });
  const ts = `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
  const P = `QA-AUTO-a882-${ts}`;

  const qty = (page: Page) => page.getByRole('textbox', { name: `כמות — ${P}`, exact: true });
  const plus = (page: Page) => page.getByRole('button', { name: `הוספת יחידה — ${P}`, exact: true });
  const minus = (page: Page) => page.getByRole('button', { name: `הפחתת יחידה — ${P}`, exact: true });
  const price = (page: Page) => page.getByRole('spinbutton', { name: `מחיר יחידה — ${P}`, exact: true });
  /** Строка товара: ближайший общий предок поля цены и кнопки удаления. */
  const row = (page: Page) => price(page).locator(`xpath=ancestor::*[.//button[@aria-label="הסרת ${P}"]][1]`);
  /** «סה"כ» строки — текст вида ₪1,000.00 внутри строки. */
  const rowTotal = (page: Page) => row(page).getByText(/^₪[\d,]+\.\d{2}$/).last();

  async function openWithProduct(page: Page) {
    await page.goto('/orders/walk-in');
    await expect(page.getByRole('heading', { level: 1, name: 'מכירה מיידית' })).toBeVisible({ timeout: 30_000 });
    const search = page.getByRole('combobox', { name: 'חיפוש מוצר להוספה למכירה' });
    await search.fill(P);
    await expect(page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' }).getByRole('option', { name: new RegExp(`^${P}\\s+נותרו`) })).toBeVisible({ timeout: 20_000 });
    await search.press('Enter');
    await expect(qty(page)).toHaveValue('1', { timeout: 15_000 });
  }

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(120_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try { await createStockedProduct(await ctx.newPage(), P, `Qa882-${ts}`, 1, 5); } finally { await ctx.close(); }
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    await cleanup(browser, [], [P]);
  });

  test('סה"כ השורה (₪1,000 / ₪10,000 / ₪100,000) מוצג במלואו מתחת לשדה המחיר ולא עולה עליו — 320/360/375/390/414; 820/1440 טבלה #a88293 @iphone @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    await page.setViewportSize({ width: 360, height: 740 });
    await openWithProduct(page);
    for (let i = 2; i <= 5; i++) {
      await plus(page).click();
      await expect(qty(page)).toHaveValue(String(i));
    }
    const SUMS: [string, string][] = [['200', '₪1,000.00'], ['2000', '₪10,000.00'], ['20000', '₪100,000.00']];
    for (const [unit, sum] of SUMS) {
      await price(page).fill(unit);
      await price(page).press('Tab');
      await expect(rowTotal(page), `сумма строки при цене ${unit} × 5`).toHaveText(sum);
      for (const W of [320, 360, 375, 390, 414, 820, 1440]) {
        await page.setViewportSize({ width: W, height: W > 800 ? 900 : 740 });
        const where = `${W}px, ${sum}`;
        await expect(rowTotal(page), where).toHaveText(sum);
        await rowTotal(page).scrollIntoViewIfNeeded();
        const t = await box(rowTotal(page), `${where}: «סה"כ» строки`);
        const p = await box(price(page), `${where}: поле цены`);
        expect(overlapArea(t, p), `${where}: «סה"כ» не заходит под поле цены`).toBe(0);
        const fits = await rowTotal(page).evaluate((e) => [e.scrollWidth, e.clientWidth]);
        expect(fits[0], `${where}: сумма не обрезана (scrollWidth ${fits[0]} / clientWidth ${fits[1]})`).toBeLessThanOrEqual(fits[1]);
        if (W < 640) {
          expect(t.y, `${where}: «סה"כ» отдельным рядом под полем цены`).toBeGreaterThanOrEqual(p.y + p.height - 1);
        } else {
          const mid = t.y + t.height / 2;
          expect(mid > p.y && mid < p.y + p.height, `${where}: табличный вид — сумма в одном ряду с полем цены`).toBe(true);
        }
        await noHorizontalScroll(page, where);
      }
      await page.setViewportSize({ width: 360, height: 740 });
    }
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
    await expect(page).toHaveURL(/\/orders$/);
  });

  test('כפתורי «+»/«−» 44×44 ולא חופפים — 360/390/820; «−» לא פעיל בכמות 1 #428d8a @iphone @orders @data', async ({ page }) => {
    await page.setViewportSize({ width: 360, height: 740 });
    await openWithProduct(page);
    for (const W of [360, 390, 820]) {
      await page.setViewportSize({ width: W, height: W > 800 ? 1180 : 740 });
      await qty(page).scrollIntoViewIfNeeded();
      const pl = await box(plus(page), `${W}px: «+»`);
      const mi = await box(minus(page), `${W}px: «−»`);
      const q = await box(qty(page), `${W}px: поле количества`);
      for (const [n, b] of [['«+»', pl], ['«−»', mi]] as const) {
        expect(b.width, `${W}px: ширина ${n}`).toBeGreaterThanOrEqual(43.5);
        expect(b.height, `${W}px: высота ${n}`).toBeGreaterThanOrEqual(43.5);
      }
      expect(overlapArea(pl, mi), `${W}px: «+» и «−» не пересекаются`).toBe(0);
      expect(overlapArea(pl, q), `${W}px: «+» и поле количества не пересекаются`).toBe(0);
      expect(overlapArea(mi, q), `${W}px: «−» и поле количества не пересекаются`).toBe(0);
      await expect(minus(page), `${W}px: «−» неактивна при количестве 1`).toBeDisabled();
      await noHorizontalScroll(page, `${W}px`);
    }
    await plus(page).click();
    await expect(qty(page)).toHaveValue('2');
    await expect(minus(page)).toBeEnabled();
    await minus(page).click();
    await expect(qty(page)).toHaveValue('1');
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
    await expect(page).toHaveURL(/\/orders$/);
  });
});
